{
  "claims": [
    {
      "text": "At approximately 09:48, Utilities crew U-A/U-B were at the gallery preparing a maintenance boundary for WO-527 while awaiting release.",
      "kind": "testimony",
      "status": "supported",
      "sourceIds": [
        "36f83919-8b7a-4ec0-a789-5d3e24cdaf6f"
      ],
      "questionId": "event-11cn0sm",
      "routedTo": []
    },
    {
      "text": "At approximately 10:00, an air-low indication appeared at RHOB and local controls showed supply complaints.",
      "kind": "testimony",
      "status": "supported",
      "sourceIds": [
        "incident-description"
      ],
      "questionId": "event-1yve653",
      "routedTo": []
    },
    {
      "text": "At approximately 10:02, RHOB requested Utilities attendance; no line opening was authorized.",
      "kind": "testimony",
      "status": "supported",
      "sourceIds": [
        "incident-description"
      ],
      "questionId": "event-dqq2tm",
      "routedTo": []
    },
    {
      "text": "At approximately 10:07, the local indication returned to normal band.",
      "kind": "testimony",
      "status": "supported",
      "sourceIds": [
        "incident-description"
      ],
      "questionId": "event-ezfbyb",
      "routedTo": []
    },
    {
      "text": "The work package cover for WO-527 shows ECP-1SC-04 Rev3 issued, but the temporary instruction attachment field is blank on the supplied copy.",
      "kind": "record",
      "status": "supported",
      "sourceIds": [
        "4df0cf7c-f4aa-49ea-a08a-ea4cd74d41f2"
      ],
      "questionId": "entity-z5f3lw",
      "routedTo": []
    },
    {
      "text": "The maintenance acceptance signature on the work package cover was not yet signed at notification time (~10:00).",
      "kind": "record",
      "status": "supported",
      "sourceIds": [
        "4df0cf7c-f4aa-49ea-a08a-ea4cd74d41f2"
      ],
      "questionId": "entity-z5f3lw",
      "routedTo": []
    },
    {
      "text": "Utilities operations is the custodian for North gallery and local indication P-U.",
      "kind": "record",
      "status": "supported",
      "sourceIds": [
        "aa0527b9-a6e3-4782-bb4e-b6cc9eb9dbcc"
      ],
      "questionId": "entity-q38m22",
      "routedTo": []
    },
    {
      "text": "RHOB operations observes receiving header H-R and local indication P-R.",
      "kind": "record",
      "status": "supported",
      "sourceIds": [
        "aa0527b9-a6e3-4782-bb4e-b6cc9eb9dbcc"
      ],
      "questionId": "entity-1ielr3j",
      "routedTo": []
    },
    {
      "text": "A maintenance work order being scheduled is not a record that the boundary has been released.",
      "kind": "record",
      "status": "supported",
      "sourceIds": [
        "aa0527b9-a6e3-4782-bb4e-b6cc9eb9dbcc"
      ],
      "questionId": "entity-q38m22",
      "routedTo": []
    },
    {
      "text": "An empty form field records no value; the reason it is empty requires other evidence.",
      "kind": "record",
      "status": "supported",
      "sourceIds": [
        "0bcc8d12-7f2d-4d73-a6ee-5fefc55c7c84"
      ],
      "questionId": "entity-z5f3lw",
      "routedTo": []
    },
    {
      "text": "Section 3.6 of change and work-record requirements states the affected ECP must be revised or an approved temporary instruction attached; draft preparation alone does not satisfy distribution.",
      "kind": "record",
      "status": "supported",
      "sourceIds": [
        "26552941-efa6-4cf3-bb10-337c6e62531d"
      ],
      "questionId": "entity-jsh6un",
      "routedTo": []
    },
    {
      "text": "U-A and U-B hold current operating qualification and energy-control authorization.",
      "kind": "record",
      "status": "supported",
      "sourceIds": [
        "fda75553-eef9-44a7-b3e0-2457fab694d9"
      ],
      "questionId": "entity-1n8efa7, entity-1nie0z6",
      "routedTo": []
    },
    {
      "text": "M-A holds dryer-maintenance qualification; boundary acceptance was pending.",
      "kind": "record",
      "status": "supported",
      "sourceIds": [
        "fda75553-eef9-44a7-b3e0-2457fab694d9"
      ],
      "questionId": "entity-46m1vr",
      "routedTo": []
    },
    {
      "text": "The interruption occurred without confirmed source location or valve state evidence.",
      "kind": "inference",
      "status": "unknown",
      "sourceIds": [
        "incident-description"
      ],
      "questionId": "unknown-1",
      "routedTo": []
    },
    {
      "text": "Whether the interruption originated at the air source, distribution system, or receiving equipment is unknown.",
      "kind": "inference",
      "status": "unknown",
      "sourceIds": [
        "incident-description"
      ],
      "questionId": "unknown-2",
      "routedTo": []
    },
    {
      "text": "Whether an approved temporary instruction was physically attached to WO-527 despite the blank field on the cover copy is unknown.",
      "kind": "inference",
      "status": "unknown",
      "sourceIds": [
        "4df0cf7c-f4aa-49ea-a08a-ea4cd74d41f2"
      ],
      "questionId": "unknown-3",
      "routedTo": []
    },
    {
      "text": "The exact pressure value and duration of the low condition before restoration are unknown.",
      "kind": "inference",
      "status": "unknown",
      "sourceIds": [
        "incident-description"
      ],
      "questionId": "unknown-4",
      "routedTo": []
    },
    {
      "text": "Whether engineering disposition occurred before the interruption is unknown.",
      "kind": "inference",
      "status": "unknown",
      "sourceIds": [
        "26552941-efa6-4cf3-bb10-337c6e62531d"
      ],
      "questionId": "unknown-5",
      "routedTo": []
    }
  ],
  "conflicts": [],
  "decision": {
    "summary": "The evidence establishes that an air interruption occurred at RHOB while a maintenance boundary was being prepared but not yet released. The work package cover shows the temporary instruction field blank and no acceptance signature; however, records do not confirm whether a physical temporary instruction existed or what valve states were present. Requirements state ECP revision or approved temporary instructions are needed before use, but evidence does not show if engineering disposition occurred prior to interruption.",
    "evidenceUsed": [
      "36f83919-8b7a-4ec0-a789-5d3e24cdaf6f",
      "incident-description",
      "aa0527b9-a6e3-4782-bb4e-b6cc9eb9dbcc",
      "4df0cf7c-f4aa-49ea-a08a-ea4cd74d41f2"
    ],
    "unknowns": [
      "Origin point of interruption (source vs distribution)",
      "Physical presence or approval status of temporary instruction",
      "Valve states during boundary preparation",
      "Exact pressure and duration values"
    ],
    "alternatives": [
      "Interruption caused by upstream source failure unrelated to maintenance work.",
      "Temporary instruction was physically attached despite blank field on cover copy.",
      "Boundary release occurred via verbal authorization not captured in records."
    ],
    "confidence": 0.85
  }
}
